import { API_URL } from "../../playwright.config";
import { expect, test, uniqueName, sample } from "../../fixtures";

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";

function yesterdayIso(): string {
  return new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

test("an expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const createRes = await member.post("/api/vendors", {
    data: { name: uniqueName("Expired Insurance Co"), category: "logistics", contact_email: "ops@expired-insurance.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = (await createRes.json()) as { id: string };

  const uploads: Array<[string, string]> = [
    ["w9", W9],
    ["contract", CONTRACT],
    ["insurance_certificate", insuranceText(yesterdayIso())],
  ];
  for (const [kind, text] of uploads) {
    const upRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
      },
    });
    expect(upRes.status(), await upRes.text()).toBe(201);
  }

  // Wait for background extraction of every document to finish.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as Array<{ status: string }>;
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitRes.status(), await submitRes.text()).toBe(200);

  // Locate the insurance certificate extraction.
  const docsRes = await member.get(`/api/vendors/${vendor.id}/documents`);
  const docs = (await docsRes.json()) as Array<{ id: string; kind: string }>;
  const insurance = docs.find((d) => d.kind === "insurance_certificate");
  expect(insurance, "insurance certificate document").toBeDefined();

  let extractionId = "";
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${insurance!.id}/extraction`);
        if (res.status() !== 200) return "";
        const body = (await res.json()) as { id: string };
        extractionId = body.id;
        return extractionId;
      },
      { timeout: 30_000 },
    )
    .not.toBe("");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await response.text();
  expect(response.status(), body).toBe(409);
  expect(JSON.parse(body).error.code, body).toBe("insurance_expired");
});
